result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/ferris.js", "content": "import {
  Group,
  Mesh,
  BoxGeometry,
  MeshBasicMaterial,
  Quaternion,
  Vector3,
} from "three";

/**
 * Build a ferris wheel.
 *
 * The returned Group is the wheel itself. Cabin pivots are placed evenly on
 * the rim; each pivot contains a cabin mesh. Spinning the wheel via
 * spinFerris counter-rotates each pivot so cabins stay upright (hanging level
 * under gravity).
 *
 * @param {{cabins?: number, radius?: number}} opts
 * @returns {{wheel: Group, pivots: Group[], cabins: Mesh[], radius: number}}
 */
export function buildFerris({ cabins = 8, radius = 5 } = {}) {
  const wheel = new Group();
  wheel.name = "ferris-wheel";

  const hub = new Group();
  hub.name = "hub";
  wheel.add(hub);

  const cabinGeometry = new BoxGeometry(1, 1, 1);
  const cabinMaterial = new MeshBasicMaterial({ color: 0xff5533 });

  const pivots = [];
  const cabinsMeshes = [];

  for (let i = 0; i < cabins; i++) {
    const angle = (i / cabins) * Math.PI * 2;

    // Pivot sits on the rim and carries the cabin. Its rotation is used to
    // counter-rotate the cabin so it stays level while the wheel spins.
    const pivot = new Group();
    pivot.name = `cabin-pivot-${i}`;
    pivot.position.set(
      Math.cos(angle) * radius,
      Math.sin(angle) * radius,
      0
    );
    wheel.add(pivot);
    pivots.push(pivot);

    const cabin = new Mesh(cabinGeometry, cabinMaterial);
    cabin.name = `cabin-${i}`;
    pivot.add(cabin);
    cabinsMeshes.push(cabin);
  }

  return { wheel, pivots, cabins: cabinsMeshes, radius };
}

/**
 * Spin the wheel to a given angle around Z, counter-rotating every cabin
 * pivot so the cabins remain upright (world rotation = identity in XY plane).
 *
 * @param {{wheel: Group, pivots: Group[]}} f
 * @param {number} angle rotation in radians
 */
export function spinFerris(f, angle) {
  f.wheel.rotation.z = angle;
  for (const pivot of f.pivots) {
    pivot.rotation.z = -angle;
  }
}

const _q = new Quaternion();

/**
 * World quaternion of cabin i's pivot frame (the cabin hangs level in this
 * frame when upright).
 *
 * @param {{pivots: Group[]}} f
 * @param {number} i
 * @returns {Quaternion}
 */
export function cabinWorldQuaternion(f, i) {
  return f.pivots[i].getWorldQuaternion(_q).clone();
}
