result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/ferris.test.js", "content": "import { describe, it, expect } from "vitest";
import { buildFerris, spinFerris, cabinWorldQuaternion } from "../src/ferris.js";
import { Matrix4, Quaternion, Vector3 } from "three";

const CABINS = 8;
const RADIUS = 6;

function makeFerris() {
  const f = buildFerris({ cabins: CABINS, radius: RADIUS });
  // World matrices need updating after transforms change.
  f.wheel.updateMatrixWorld(true);
  return f;
}

describe("buildFerris", () => {
  it("places cabins evenly spaced on the rim", () => {
    const f = makeFerris();

    const angles = f.pivots.map((p) =>
      Math.atan2(p.position.y, p.position.x)
    );

    for (let i = 0; i < CABINS; i++) {
      const a = angles[i];
      const b = angles[(i + 1) % CABINS];
      let gap = b - a;
      if (i === CABINS - 1) gap += Math.PI * 2; // wrap-around
      expect(Math.abs(gap - (Math.PI * 2) / CABINS)).toBeLessThanOrEqual(1e-9);
    }

    for (const pivot of f.pivots) {
      expect(pivot.position.length()).toBeCloseTo(RADIUS, 9);
    }
  });
});

describe("spinFerris keeps cabins upright", () => {
  it("every cabin world quaternion equals identity at angle 0.7 rad", () => {
    const f = makeFerris();
    spinFerris(f, 0.7);
    f.wheel.updateMatrixWorld(true);

    const identity = new Quaternion(0, 0, 0, 1);
    for (let i = 0; i < CABINS; i++) {
      const q = cabinWorldQuaternion(f, i);
      expect(Math.abs(q.x - identity.x)).toBeLessThan(1e-6);
      expect(Math.abs(q.y - identity.y)).toBeLessThan(1e-6);
      expect(Math.abs(q.z - identity.z)).toBeLessThan(1e-6);
      expect(Math.abs(q.w - identity.w)).toBeLessThan(1e-6);
    }
  });

  it("cabin world positions still lie on the radius circle after spinning", () => {
    const f = makeFerris();
    spinFerris(f, 0.7);
    f.wheel.updateMatrixWorld(true);

    for (const pivot of f.pivots) {
      const pos = new Vector3().setFromMatrixPosition(pivot.matrixWorld);
      expect(pos.distanceTo(new Vector3(0, 0, 0))).toBeCloseTo(RADIUS, 9);
    }
  });

  it("spinning by 2*PI returns cabin 0 to its original world position", () => {
    const f = makeFerris();

    const before = new Vector3()
      .setFromMatrixPosition(f.cabins[0].matrixWorld)
      .clone();

    spinFerris(f, Math.PI * 2);
    f.wheel.updateMatrixWorld(true);

    const after = new Vector3().setFromMatrixPosition(f.cabins[0].matrixWorld);

    expect(after.distanceTo(before)).toBeLessThan(1e-9);
  });
});
"})
